class PanelQuad
{
  char data[0x190];
public:
  virtual ~PanelQuad() {}
  virtual void Init();
  virtual void TurnOn(bool);
  virtual void SetLayer(int);
  virtual void Rotate(float);
  virtual void Rotate(float, float, float);
  virtual void Update(float);
  virtual void Draw(int = 0, float = -1.0f);
  virtual void SetColor(float, float, float, float);
  virtual void SetColor(int);
  virtual void SetZ(float);
  virtual void SetUV(float, float, float, float);
  virtual bool IsOn() const;
  virtual void SetPos(float xa, float ya, float xb, float yb);
  virtual void SetPos(float xa, float ya);
  virtual void SetPos(float, float, float, float, float, float, float, float);
  virtual void GetPos(float &xa, float &ya, float &xb, float &yb);
};

class MainFrontEnd
{
  char prefix[0x19c];
  enum { MainCareerEntry = 1, MainEnd = 5, num_boxes = 9 };
  PanelQuad *boxes[MainEnd][num_boxes];
public:
  void ResizeCareerBox(int h);
};

void MainFrontEnd::ResizeCareerBox(int h)
{
	float xa, ya, xb, yb;
	for(int i=3; i<num_boxes; i++)
	{
		boxes[MainCareerEntry][i]->GetPos(xa, ya, xb, yb);
		if(i < 6) boxes[MainCareerEntry][i]->SetPos(xa, ya, xb, h);
		else boxes[MainCareerEntry][i]->SetPos(xa, h, xb, h+(yb-ya));
	}
}
